using System;

namespace Core;

public enum LifeState
{
	Alive,
	Dead,
}
public struct DamageTypes
{
	public static string DMG_GENERIC = "generic";                       // generic damage -- do not use if you want players to flinch and bleed!
	public static string DMG_CRUSH = "crush";                           // crushed by falling or moving object. 
																		// NOTE: It's assumed crush damage is occurring as a result of physics collision, so no extra physics force is generated by crush damage.
																		// DON'T use DMG_CRUSH when damaging entities unless it's the result of a physics collision. You probably want DMG_CLUB instead.
	public static string DMG_BULLET = "bullet";                         // shot
	public static string DMG_SLASH = "slash";                           // cut, clawed, stabbed
	public static string DMG_BURN = "burn";                             // heat burned
	public static string DMG_VEHICLE = "vehicle";                       // hit by a vehicle
	public static string DMG_FALL = "fall";                             // fell too far
	public static string DMG_CLUB = "club";                             // crowbar, punch, headbutt
	public static string DMG_SHOCK = "shock";                           // electric shock
	public static string DMG_SONIC = "sonic";                           // sound pulse shockwave
	public static string DMG_ENERGYBEAM = "energybeam";                 // laser or other high energy beam 
	public static string DMG_PREVENT_PHYSICS_FORCE = "nophysforce";     // Prevent a physics force 
	public static string DMG_NEVERGIB = "nevergib";                     // with this bit OR'd in, no damage type will be able to gib victims upon death
	public static string DMG_ALWAYSGIB = "alwaysgib";                   // with this bit OR'd in, any damage type can be made to gib victims upon death.
	public static string DMG_DROWN = "drown";                           // Drowning


	public static string DMG_PARALYZE = "paralyze";                     // slows affected creature down
	public static string DMG_NERVEGAS = "nervegas";                     // nerve toxins, very bad
	public static string DMG_POISON = "poison";                         // blood poisoning - heals over time like drowning damage
	public static string DMG_RADIATION = "radiation";                   // radiation exposure
	public static string DMG_DROWNRECOVER = "drownrecover";             // drowning recovery
	public static string DMG_ACID = "acid";                             // toxic chemicals or acid burns
	public static string DMG_SLOWBURN = "slowburn";                     // in an oven

	public static string DMG_REMOVENORAGDOLL = "removeonragdoll";       // with this bit OR'd in, no ragdoll will be created, and the target will be quietly removed.
																		// use this to kill an entity that you've already got a server-side ragdoll for

	public static string DMG_PHYSGUN = "physgun";                       // Hit by manipulator. Usually doesn't do any damage.
	public static string DMG_PLASMA = "plasma";                         // Shot by Cremator
	public static string DMG_AIRBOAT = "airboat";                       // Hit by the airboat's gun

	public static string DMG_DISSOLVE = "dissolve";                     // Dissolving!
	public static string DMG_BLAST_SURFACE = "blastsurface";            // A blast on the surface of water that cannot harm things underwater
	public static string DMG_DIRECT = "direct";
	public static string DMG_BUCKSHOT = "buckshot";                     // not quite a bullet. Little, rounder, different.

	public static string DMG_BLAST = "explosion";                       // explosion
}

