	DMG_ALWAYSGIB,      // with this bit OR'd in, any damage type can be made to gib victims upon death.
	DMG_DROWN,          // Drowning


	DMG_PARALYZE,       // slows affected creature down
	DMG_NERVEGAS,       // nerve toxins, very bad
