	DMG_SLOWBURN,       // in an oven

	DMG_REMOVENORAGDOLL,// with this bit OR'd in, no ragdoll will be created, and the target will be quietly removed.
						// use this to kill an entity that you've already got a server-side ragdoll for

	DMG_PHYSGUN,        // Hit by manipulator. Usually doesn't do any damage.
	DMG_PLASMA,         // Shot by Cremator
	DMG_AIRBOAT,        // Hit by the airboat's gun

	DMG_DISSOLVE,       // Dissolving!
	DMG_BLAST_SURFACE,  // A blast on the surface of water that cannot harm things underwater
	DMG_DIRECT,
	DMG_BUCKSHOT,       // not quite a bullet. Little, rounder, different.

	DMG_BLAST,          // explosion
}

[Obsolete( "Damagables are done using DamageInfo and CoreDamageInfo" )]
public class TakeDamageInfo
{
	public Vector3 DamageForce { get; set; }
	public Vector3 DamagePosition { get; set; } //position players are told damage is coming from
	public Vector3 ReportedPosition { get; set; }
	public GameObject Inflictor { get; set; } //the weapon or rocket (or player) that is dealing the damage
	public GameObject Attacker { get; set; } //the character who originated the attack (like a player or an AI).
	public BaseCombatWeapon Weapon { get; set; } // the weapon that did the attack.
												 // For hitscan weapons, it'll be the same as the inflictor. For projectile weapons, the projectile 
												 // is the inflictor, and this contains the weapon that created the projectile.
	public float Damage { get; set; }
	public float BaseDamage { get; set; } //the damage amount before skill level adjustments are made, used to get uniform damage forces
	public int bitsType { get; set; }
	public Hitbox Hitbox { get; set; }

	public TakeDamageInfo()
	{
		DamageForce = Vector3.Zero;
		DamagePosition = Vector3.Zero;
		ReportedPosition = Vector3.Zero;
		Damage = 0f;
		BaseDamage = 0f;
		bitsType = 0;
	}
	public TakeDamageInfo( GameObject inflictor, GameObject attacker, float damage, DamageType type )
	{
		DamageForce = Vector3.Zero;
		DamagePosition = Vector3.Zero;
		ReportedPosition = Vector3.Zero;
		Inflictor = inflictor;
		Attacker = attacker;
		Damage = damage;

		AddDamageType( type );
	}
	public TakeDamageInfo( GameObject inflictor, GameObject attacker, BaseCombatWeapon weapon, float damage, DamageType type )
	{
		DamageForce = Vector3.Zero;
		DamagePosition = Vector3.Zero;
		ReportedPosition = Vector3.Zero;
		Inflictor = inflictor;
		Attacker = attacker;
		Weapon = weapon;
		Damage = damage;

		AddDamageType( type );
	}
	public TakeDamageInfo( GameObject inflictor, GameObject attacker, Vector3 damageForce, Vector3 damagePosition, float damage, DamageType type, Vector3 reportedPosition = new Vector3() )
	{
		DamageForce = damageForce;
		DamagePosition = damagePosition;
		ReportedPosition = reportedPosition;
		Inflictor = inflictor;
		Attacker = attacker;
		Damage = damage;

		AddDamageType( type );
	}
	//public TakeDamageInfo(GameObject inflictor, GameObject attacker, BaseWeapon weapon, Vector3 damageForce, Vector3 damagePosition, float damage, DamageType type, Vector3 reportedPosition = new Vector3()) { }

	public void AddDamageType( DamageType type ) { bitsType |= (1 << (int)type); }

	public bool HasDamageType( DamageType type ) { return (bitsType & (1 << (int)type)) != 0; }

	public void AdjustPlayerDamageTakenForSkillLevel() { } // TODO

	public void AdjustDamageScale( float scale )
	{
		if ( BaseDamage == 0f )
			BaseDamage = Damage;

		Damage = BaseDamage * scale;
	}
}

[Obsolete]
public delegate void OnTakeDamageAction( TakeDamageInfo DamageInfo );

[Obsolete( "Damagables are done using base Component.IDamagable" )]
public class TakeDamageController : Component
{
	[Property] public OnTakeDamageAction OnTakeDamage { get; set; }

	public void TakeDamage( TakeDamageInfo damageInfo )
	{
		//		dispatch action
		OnTakeDamage?.Invoke( damageInfo );
		//		distrubute to gameobjets
		//		GameObject.Components.Get<BasePlayer>()?.OnTakeDamage( damageInfo );

		if ( Tags.Has( "player_main" ) && GameObject.Parent != null )
			GameObject.Parent.Components.GetOrCreate<TakeDamageController>()?.TakeDamage( damageInfo );

		//		GameObject.Components.Get<BaseNpc>()?.OnTakeDamage( damageInfo );
		GameObject.Components.Get<Core.GameProp>()?.OnDamage( new DamageInfo( damageInfo.Damage, damageInfo.Attacker, damageInfo.Inflictor ) );

		//		if we have a ridid body add the damage force to it
		GameObject.Components.Get<Rigidbody>()?.PhysicsBody.ApplyImpulseAt( damageInfo.DamagePosition, damageInfo.DamageForce * 200f );
	}
}


